import numpy as np
from scipy.optimize import minimize

def calculate_R_bent(params, n):
    # params: a, d, k, d_prime
    a, d, k, d_prime = params
    k = int(round(k))
    if k < 1 or k >= n:
        return 1e10 # Penalty

    f = np.zeros(n)
    for i in range(n):
        if i < k:
            f[i] = a + i * d
        else:
            f[i] = a + (k-1) * d + (i - (k-1)) * d_prime

    if np.any(f < 0) or d_prime > d:
        return 1e10

    num = np.sum(f**2)
    den = np.sum((np.arange(1, n+1)) * (f**2))
    return -num / den

def find_max_R_bent(n):
    overall_max = 0
    for k in range(1, n):
        # For a fixed k, we can optimize a, d, d_prime
        res = minimize(calculate_R_bent, [1.0, 0.1, k, 0.0], args=(n,), 
                       bounds=[(0, None), (None, None), (None, None), (None, None)])
        overall_max = max(overall_max, -res.fun)
    return overall_max

for n in range(3, 7):
    print(f"n={n}, max_R_bent={find_max_R_bent(n)}")
